class Qwen3VLVisionModel(Qwen3VLPreTrainedModel):
    config: Qwen3VLVisionConfig
    _no_split_modules = ["Qwen3VLVisionBlock"]

    def __init__(self, config, *inputs, **kwargs) -> None:
        super().__init__(config, *inputs, **kwargs)
        self.spatial_merge_size = config.spatial_merge_size
        self.patch_size = config.patch_size
        self.spatial_merge_unit = self.spatial_merge_size * self.spatial_merge_size

        self.patch_embed = Qwen3VLVisionPatchEmbed(
            config=config,
        )

        self.pos_embed = nn.Embedding(config.num_position_embeddings, config.hidden_size)
        self.num_grid_per_side = int(config.num_position_embeddings**0.5)

        head_dim = config.hidden_size // config.num_heads
        self.rotary_pos_emb = Qwen3VLVisionRotaryEmbedding(head_dim // 2)

        self.blocks = nn.ModuleList([Qwen3VLVisionBlock(config) for _ in range(config.depth)])
        self.merger = Qwen3VLVisionPatchMerger(
            config=config,
            use_postshuffle_norm=False,
        )

        self.deepstack_visual_indexes = config.deepstack_visual_indexes
        self.deepstack_merger_list = nn.ModuleList(
            [
                Qwen3VLVisionPatchMerger(
                    config=config,
                    use_postshuffle_norm=True,
                )
                for _ in range(len(config.deepstack_visual_indexes))
            ]
        )

        self.gradient_checkpointing = False

    def rot_pos_emb(self, grid_thw: torch.Tensor) -> torch.Tensor:
        merge_size = self.spatial_merge_size

        max_hw = int(grid_thw[:, 1:].max().item())
        freq_table = self.rotary_pos_emb(max_hw)  # (max_hw, dim // 2)
        device = freq_table.device

        total_tokens = int(torch.prod(grid_thw, dim=1).sum().item())
        pos_ids = torch.empty((total_tokens, 2), dtype=torch.long, device=device)

        offset = 0
        for num_frames, height, width in grid_thw:
            merged_h, merged_w = height // merge_size, width // merge_size

            block_rows = torch.arange(merged_h, device=device)  # block row indices
            block_cols = torch.arange(merged_w, device=device)  # block col indices
            intra_row = torch.arange(merge_size, device=device)  # intra-block row offsets
            intra_col = torch.arange(merge_size, device=device)  # intra-block col offsets

            # Compute full-resolution positions
            row_idx = block_rows[:, None, None, None] * merge_size + intra_row[None, None, :, None]
            col_idx = block_cols[None, :, None, None] * merge_size + intra_col[None, None, None, :]

            row_idx = row_idx.expand(merged_h, merged_w, merge_size, merge_size).reshape(-1)
            col_idx = col_idx.expand(merged_h, merged_w, merge_size, merge_size).reshape(-1)

            coords = torch.stack((row_idx, col_idx), dim=-1)

            if num_frames > 1:
                coords = coords.repeat(num_frames, 1)

            num_tokens = coords.shape[0]
            pos_ids[offset : offset + num_tokens] = coords
            offset += num_tokens

        embeddings = freq_table[pos_ids]  # lookup rotary embeddings
        embeddings = embeddings.flatten(1)
        return embeddings

    def fast_pos_embed_interpolate(self, grid_thw):
        grid_ts, grid_hs, grid_ws = grid_thw[:, 0], grid_thw[:, 1], grid_thw[:, 2]

        idx_list = [[] for _ in range(4)]
        weight_list = [[] for _ in range(4)]

        for t, h, w in zip(grid_ts, grid_hs, grid_ws):
            h_idxs = torch.linspace(0, self.num_grid_per_side - 1, h)
            w_idxs = torch.linspace(0, self.num_grid_per_side - 1, w)

            h_idxs_floor = h_idxs.int()
            w_idxs_floor = w_idxs.int()
            h_idxs_ceil = (h_idxs.int() + 1).clip(max=self.num_grid_per_side - 1)
            w_idxs_ceil = (w_idxs.int() + 1).clip(max=self.num_grid_per_side - 1)

            dh = h_idxs - h_idxs_floor
            dw = w_idxs - w_idxs_floor

            base_h = h_idxs_floor * self.num_grid_per_side
            base_h_ceil = h_idxs_ceil * self.num_grid_per_side

            indices = [
                (base_h[None].T + w_idxs_floor[None]).flatten(),
                (base_h[None].T + w_idxs_ceil[None]).flatten(),
                (base_h_ceil[None].T + w_idxs_floor[None]).flatten(),
                (base_h_ceil[None].T + w_idxs_ceil[None]).flatten(),
            ]

            weights = [
                ((1 - dh)[None].T * (1 - dw)[None]).flatten(),
                ((1 - dh)[None].T * dw[None]).flatten(),
                (dh[None].T * (1 - dw)[None]).flatten(),
                (dh[None].T * dw[None]).flatten(),
            ]

            for i in range(4):
                idx_list[i].extend(indices[i].tolist())
                weight_list[i].extend(weights[i].tolist())

        idx_tensor = torch.tensor(idx_list, dtype=torch.long, device=self.pos_embed.weight.device)
        weight_tensor = torch.tensor(
            weight_list, dtype=self.pos_embed.weight.dtype, device=self.pos_embed.weight.device
        )
        pos_embeds = self.pos_embed(idx_tensor) * weight_tensor[:, :, None]
        patch_pos_embeds = pos_embeds[0] + pos_embeds[1] + pos_embeds[2] + pos_embeds[3]

        patch_pos_embeds = patch_pos_embeds.split([h * w for h, w in zip(grid_hs, grid_ws)])

        patch_pos_embeds_permute = []
        merge_size = self.config.spatial_merge_size
        for pos_embed, t, h, w in zip(patch_pos_embeds, grid_ts, grid_hs, grid_ws):
            pos_embed = pos_embed.repeat(t, 1)
            pos_embed = (
                pos_embed.view(t, h // merge_size, merge_size, w // merge_size, merge_size, -1)
                .permute(0, 1, 3, 2, 4, 5)
                .flatten(0, 4)
            )
            patch_pos_embeds_permute.append(pos_embed)
        patch_pos_embeds = torch.cat(patch_pos_embeds_permute)
        return patch_pos_embeds

    def forward(self, hidden_states: torch.Tensor, grid_thw: torch.Tensor, **kwargs) -> torch.Tensor:
        """
        Args:
            hidden_states (`torch.Tensor` of shape `(seq_len, hidden_size)`):
                The final hidden states of the model.
            grid_thw (`torch.Tensor` of shape `(num_images_or_videos, 3)`):
                The temporal, height and width of feature shape of each image in LLM.

        Returns:
            `torch.Tensor`: hidden_states.
        """
        hidden_states = self.patch_embed(hidden_states)

        pos_embeds = self.fast_pos_embed_interpolate(grid_thw)
        hidden_states = hidden_states + pos_embeds

        rotary_pos_emb = self.rot_pos_emb(grid_thw)

        seq_len, _ = hidden_states.size()
        hidden_states = hidden_states.reshape(seq_len, -1)
        rotary_pos_emb = rotary_pos_emb.reshape(seq_len, -1)
        emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
        position_embeddings = (emb.cos(), emb.sin())

        cu_seqlens = torch.repeat_interleave(grid_thw[:, 1] * grid_thw[:, 2], grid_thw[:, 0]).cumsum(
            dim=0,
            # Select dtype based on the following factors:
            #  - FA2 requires that cu_seqlens_q must have dtype int32
            #  - torch.onnx.export requires that cu_seqlens_q must have same dtype as grid_thw
            # See https://github.com/huggingface/transformers/pull/34852 for more information
            dtype=grid_thw.dtype if torch.jit.is_tracing() else torch.int32,
        )
        cu_seqlens = F.pad(cu_seqlens, (1, 0), value=0)

        deepstack_feature_lists = []
        for layer_num, blk in enumerate(self.blocks):
            hidden_states = blk(
                hidden_states,
                cu_seqlens=cu_seqlens,
                position_embeddings=position_embeddings,
                **kwargs,
            )
            if layer_num in self.deepstack_visual_indexes:
                deepstack_feature = self.deepstack_merger_list[self.deepstack_visual_indexes.index(layer_num)](
                    hidden_states
                )
                deepstack_feature_lists.append(deepstack_feature)

        hidden_states = self.merger(hidden_states)

        return hidden_states, deepstack_feature_lists


@auto_docstring(
    custom_intro=(
        "Text part of Qwen3VL, "
        "not a pure text-only model, as DeepStack integrates visual features into the early hidden states."
    )
)
class Qwen3VLTextModel(Qwen3VLPreTrainedModel):
    config: Qwen3VLTextConfig
    _no_split_modules = ["Qwen3VLTextDecoderLayer"]

    def __init__(self, config: Qwen3VLTextConfig):
        super().__init__(config)
        self.padding_idx = config.pad_token_id
        self.vocab_size = config.vocab_size

        self.embed_tokens = nn.Embedding(config.vocab_size, config.hidden_size, self.padding_idx)
        self.layers = nn.ModuleList(
            [Qwen3VLTextDecoderLayer(config, layer_idx) for layer_idx in range(config.num_hidden_layers)]
        )
        self.norm = Qwen3VLTextRMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.rotary_emb = Qwen3VLTextRotaryEmbedding(config=config)
        self.gradient_checkpointing = False

        # Initialize weights and apply final processing
        self.post_init()

    @check_model_inputs
    @auto_docstring
    def forward(
        self,
        input_ids: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        use_cache: Optional[bool] = None,
        cache_position: Optional[torch.LongTensor] = None,
        # args for deepstack
        visual_pos_masks: Optional[torch.Tensor] = None,
        deepstack_visual_embeds: Optional[list[torch.Tensor]] = None,
        **kwargs: Unpack[FlashAttentionKwargs],
    ) -> Union[tuple, BaseModelOutputWithPast]:
        r"""
        visual_pos_masks (`torch.Tensor` of shape `(batch_size, seqlen)`, *optional*):
            The mask of the visual positions.
        deepstack_visual_embeds (`list[torch.Tensor]`, *optional*):
            The deepstack visual embeddings. The shape is (num_layers, visual_seqlen, embed_dim).
            The feature is extracted from the different visual encoder layers, and fed to the decoder
            hidden states. It's from the paper DeepStack(https://arxiv.org/abs/2406.04334).
        """
        # print("In forward function of Qwen3VLTextModel")
        # print(f"input_ids : {input_ids}")
        # print(f"inputs_embeds : {inputs_embeds.shape if inputs_embeds is not None else None}")
        # print(f"position_ids : {position_ids.shape if position_ids is not None else None}")
        # print(f"attention_mask : {attention_mask.shape if attention_mask is not None else None}")
        # print(f"past_key_values : {past_key_values.shape if past_key_values is not None else None}")
        # print(f"cache_position : {cache_position.shape if cache_position is not None else None}")
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        # torch.jit.trace() doesn't support cache objects in the output
        if use_cache and past_key_values is None and not torch.jit.is_tracing():
            past_key_values = DynamicCache(config=self.config)
        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)

        if cache_position is None:
            past_seen_tokens = past_key_values.get_seq_length() if past_key_values is not None else 0
            cache_position = torch.arange(
                past_seen_tokens, past_seen_tokens + inputs_embeds.shape[1], device=inputs_embeds.device
            )

        # the hard coded `3` is for temporal, height and width.
        if position_ids is None:
            position_ids = cache_position.view(1, 1, -1).expand(3, inputs_embeds.shape[0], -1)
        elif position_ids.ndim == 2:
            position_ids = position_ids[None, ...].expand(3, position_ids.shape[0], -1)

        if position_ids.ndim == 3 and position_ids.shape[0] == 4:
            text_position_ids = position_ids[0]
            position_ids = position_ids[1:]
        else:
            text_position_ids = position_ids[0]

        attention_mask = create_causal_mask(
            config=self.config,
            input_embeds=inputs_embeds,
            attention_mask=attention_mask,
            cache_position=cache_position,
            past_key_values=past_key_values,
            position_ids=text_position_ids,
        )

        hidden_states = inputs_embeds

        # create position embeddings to be shared across the decoder layers
        position_embeddings = self.rotary_emb(hidden_states, position_ids)

        # decoder layers
        for layer_idx, decoder_layer in enumerate(self.layers):
            layer_outputs = decoder_layer(
                hidden_states,
                attention_mask=attention_mask,
                position_ids=text_position_ids,
                past_key_values=past_key_values,
                cache_position=cache_position,
                position_embeddings=position_embeddings,
                **kwargs,
            )
            hidden_states = layer_outputs

            # add visual features to the hidden states of first several layers
            if deepstack_visual_embeds is not None and layer_idx in range(len(deepstack_visual_embeds)):
                hidden_states = self._deepstack_process(
                    hidden_states,
                    visual_pos_masks,
                    deepstack_visual_embeds[layer_idx],
                )

        hidden_states = self.norm(hidden_states)

        return BaseModelOutputWithPast(
            last_hidden_state=hidden_states,
            past_key_values=past_key_values,
        )

    def _deepstack_process(
        self, hidden_states: torch.Tensor, visual_pos_masks: torch.Tensor, visual_embeds: torch.Tensor
    ):
        visual_pos_masks = visual_pos_masks.to(hidden_states.device)
        visual_embeds = visual_embeds.to(hidden_states.device, hidden_states.dtype)
        local_this = hidden_states[visual_pos_masks, :].clone() + visual_embeds
        hidden_states[visual_pos_masks, :] = local_this
        return hidden_states


@auto_docstring
class Qwen3VLModel(Qwen3VLPreTrainedModel):
    base_model_prefix = ""
    _checkpoint_conversion_mapping = {}
    # Reference: fix gemma3 grad acc #37208
    accepts_loss_kwargs = False
    config: Qwen3VLConfig
    _no_split_modules = ["Qwen3VLTextDecoderLayer", "Qwen3VLVisionBlock"]

    def __init__(self, config):
        super().__init__(config)
        self.visual = Qwen3VLVisionModel._from_config(config.vision_config)
        self.language_model = Qwen3VLTextModel._from_config(config.text_config)
        self.rope_deltas = None  # cache rope_deltas here

        # Initialize weights and apply final processing
        self.post_init()

    def get_input_embeddings(self):
        return self.language_model.get_input_embeddings()

    def set_input_embeddings(self, value):
        self.language_model.set_input_embeddings(value)

    def set_decoder(self, decoder):
        self.language_model = decoder

    def get_decoder(self):
        return self.language_model

    def get_rope_index(
        self,
        input_ids: Optional[torch.LongTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """Different from the original implementation, Qwen3VL use timestamps rather than absolute time position ids."""

        # Since we use timestamps to seperate videos, like <t1> <vision_start> <frame1> <vision_end> <t2> <vision_start> <frame2> <vision_end>, the video_grid_thw should also be split
        if video_grid_thw is not None:
            video_grid_thw = torch.repeat_interleave(video_grid_thw, video_grid_thw[:, 0], dim=0)
            video_grid_thw[:, 0] = 1

        spatial_merge_size = self.config.vision_config.spatial_merge_size
        image_token_id = self.config.image_token_id
        video_token_id = self.config.video_token_id
        vision_start_token_id = self.config.vision_start_token_id
        mrope_position_deltas = []
        if input_ids is not None and (image_grid_thw is not None or video_grid_thw is not None):
            total_input_ids = input_ids
            if attention_mask is None:
                attention_mask = torch.ones_like(total_input_ids)
            position_ids = torch.ones(
                3,
                input_ids.shape[0],
                input_ids.shape[1],
                dtype=input_ids.dtype,
                device=input_ids.device,
            )
            image_index, video_index = 0, 0
            attention_mask = attention_mask.to(total_input_ids.device)
            for i, input_ids in enumerate(total_input_ids):
                input_ids = input_ids[attention_mask[i] == 1]
                image_nums, video_nums = 0, 0
                vision_start_indices = torch.argwhere(input_ids == vision_start_token_id).squeeze(1)
                vision_tokens = input_ids[vision_start_indices + 1]
                image_nums = (vision_tokens == image_token_id).sum()
                video_nums = (vision_tokens == video_token_id).sum()
                input_tokens = input_ids.tolist()
                llm_pos_ids_list: list = []
                st = 0
                remain_images, remain_videos = image_nums, video_nums
                for _ in range(image_nums + video_nums):
                    if image_token_id in input_tokens and remain_images > 0:
                        ed_image = input_tokens.index(image_token_id, st)
                    else:
                        ed_image = len(input_tokens) + 1
                    if video_token_id in input_tokens and remain_videos > 0:
                        ed_video = input_tokens.index(video_token_id, st)
                    else:
                        ed_video = len(input_tokens) + 1
                    if ed_image < ed_video:
                        t, h, w = (
                            image_grid_thw[image_index][0],
                            image_grid_thw[image_index][1],
                            image_grid_thw[image_index][2],
                        )
                        image_index += 1
                        remain_images -= 1
                        ed = ed_image

                    else:
                        t, h, w = (
                            video_grid_thw[video_index][0],
                            video_grid_thw[video_index][1],
                            video_grid_thw[video_index][2],
                        )
                        video_index += 1
                        remain_videos -= 1
                        ed = ed_video
                    llm_grid_t, llm_grid_h, llm_grid_w = (
                        t.item(),
                        h.item() // spatial_merge_size,
                        w.item() // spatial_merge_size,
                    )
                    text_len = ed - st

                    st_idx = llm_pos_ids_list[-1].max() + 1 if len(llm_pos_ids_list) > 0 else 0
                    llm_pos_ids_list.append(torch.arange(text_len).view(1, -1).expand(3, -1) + st_idx)

                    # t_index is always 0 because llm_grid_t is always 1 (we use timestamps to encode the temporal information for videos)
                    t_index = torch.arange(llm_grid_t).view(-1, 1).expand(-1, llm_grid_h * llm_grid_w).flatten()
                    h_index = torch.arange(llm_grid_h).view(1, -1, 1).expand(llm_grid_t, -1, llm_grid_w).flatten()
                    w_index = torch.arange(llm_grid_w).view(1, 1, -1).expand(llm_grid_t, llm_grid_h, -1).flatten()
                    llm_pos_ids_list.append(torch.stack([t_index, h_index, w_index]) + text_len + st_idx)
                    st = ed + llm_grid_t * llm_grid_h * llm_grid_w

                if st < len(input_tokens):
                    st_idx = llm_pos_ids_list[-1].max() + 1 if len(llm_pos_ids_list) > 0 else 0
                    text_len = len(input_tokens) - st
                    llm_pos_ids_list.append(torch.arange(text_len).view(1, -1).expand(3, -1) + st_idx)

                llm_positions = torch.cat(llm_pos_ids_list, dim=1).reshape(3, -1)
                position_ids[..., i, attention_mask[i] == 1] = llm_positions.to(position_ids.device)
                mrope_position_deltas.append(llm_positions.max() + 1 - len(total_input_ids[i]))
            mrope_position_deltas = torch.tensor(mrope_position_deltas, device=input_ids.device).unsqueeze(1)
            return position_ids, mrope_position_deltas
        else:
            if attention_mask is not None:
                position_ids = attention_mask.long().cumsum(-1) - 1
                position_ids.masked_fill_(attention_mask == 0, 1)
                position_ids = position_ids.unsqueeze(0).expand(3, -1, -1).to(attention_mask.device)
                max_position_ids = position_ids.max(0, keepdim=False)[0].max(-1, keepdim=True)[0]
                mrope_position_deltas = max_position_ids + 1 - attention_mask.shape[-1]
            else:
                position_ids = (
                    torch.arange(input_ids.shape[1], device=input_ids.device)
                    .view(1, 1, -1)
                    .expand(3, input_ids.shape[0], -1)
                )
                mrope_position_deltas = torch.zeros(
                    [input_ids.shape[0], 1],
                    device=input_ids.device,
                    dtype=input_ids.dtype,
                )

            return position_ids, mrope_position_deltas

    def get_video_features(
        self, pixel_values_videos: torch.FloatTensor, video_grid_thw: Optional[torch.LongTensor] = None
    ):
        """
        Encodes videos into continuous embeddings that can be forwarded to the language model. The deepstack visual features are also returned.

        Args:
            pixel_values_videos (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
                The tensors corresponding to the input videos.
            video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
                The temporal, height and width of feature shape of each video in LLM.
        """
        # Same implementation as for images
        return self.get_image_features(pixel_values_videos, video_grid_thw)

    def get_image_features(self, pixel_values: torch.FloatTensor, image_grid_thw: Optional[torch.LongTensor] = None):
        """
        Encodes images into continuous embeddings that can be forwarded to the language model. The deepstack visual features are also returned.

        Args:
            pixel_values (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
                The tensors corresponding to the input images.
            image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
                The temporal, height and width of feature shape of each image in LLM.
        """
        pixel_values = pixel_values.type(self.visual.dtype)
        image_embeds, deepstack_image_embeds = self.visual(pixel_values, grid_thw=image_grid_thw)
        split_sizes = (image_grid_thw.prod(-1) // self.visual.spatial_merge_size**2).tolist()
        image_embeds = torch.split(image_embeds, split_sizes)
        return image_embeds, deepstack_image_embeds

    def get_placeholder_mask(
        self,
        input_ids: torch.LongTensor,
        inputs_embeds: torch.FloatTensor,
        image_features: Optional[torch.FloatTensor] = None,
        video_features: Optional[torch.FloatTensor] = None,
    ):
        """
        Obtains multimodal placeholder mask from `input_ids` or `inputs_embeds`, and checks that the placeholder token count is
        equal to the length of multimodal features. If the lengths are different, an error is raised.
        """
        if input_ids is None:
            special_image_mask = inputs_embeds == self.get_input_embeddings()(
                torch.tensor(self.config.image_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_image_mask = special_image_mask.all(-1)
            special_video_mask = inputs_embeds == self.get_input_embeddings()(
                torch.tensor(self.config.video_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_video_mask = special_video_mask.all(-1)
        else:
            special_image_mask = input_ids == self.config.image_token_id
            special_video_mask = input_ids == self.config.video_token_id

        n_image_tokens = special_image_mask.sum()
        special_image_mask = special_image_mask.unsqueeze(-1).expand_as(inputs_embeds).to(inputs_embeds.device)
        if image_features is not None and inputs_embeds[special_image_mask].numel() != image_features.numel():
            raise ValueError(
                f"Image features and image tokens do not match: tokens: {n_image_tokens}, features {image_features.shape[0]}"
            )

        n_video_tokens = special_video_mask.sum()
        special_video_mask = special_video_mask.unsqueeze(-1).expand_as(inputs_embeds).to(inputs_embeds.device)
        if video_features is not None and inputs_embeds[special_video_mask].numel() != video_features.numel():
            raise ValueError(
                f"Videos features and video tokens do not match: tokens: {n_video_tokens}, features {video_features.shape[0]}"
            )

        return special_image_mask, special_video_mask

    @auto_docstring
    @check_model_inputs
    def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        cache_position: Optional[torch.LongTensor] = None,
        # use_cache = False,
        **kwargs: Unpack[TransformersKwargs],
    ) -> Union[tuple, Qwen3VLModelOutputWithPast]:
        r"""
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.
        """
        # print("In forward function of Qwen3VL model")
        # print(f"input_ids : {input_ids.shape}")
        # print(f"input_ids : {input_ids}")
        # print(f"pixel_values : {pixel_values.shape if pixel_values is not None else None}")
        # print(f"image_grid_thw : {image_grid_thw if image_grid_thw is not None else None}")
        # print(f"position_ids : {position_ids.shape if position_ids is not None else None}")
        # print(f"attention_mask : {attention_mask.shape if attention_mask is not None else None}")
        # print(f"past_key_values : {past_key_values.shape if past_key_values is not None else None}")
        # print(f"inputs_embeds : {inputs_embeds.shape if inputs_embeds is not None else None}")
        # print(f"cache_position : {cache_position.shape if cache_position is not None else None}")
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        if inputs_embeds is None:
            inputs_embeds = self.get_input_embeddings()(input_ids)

        image_mask = None
        video_mask = None

        if pixel_values is not None:
            image_embeds, deepstack_image_embeds = self.get_image_features(pixel_values, image_grid_thw)
            image_embeds = torch.cat(image_embeds, dim=0).to(inputs_embeds.device, inputs_embeds.dtype)
            image_mask, _ = self.get_placeholder_mask(
                input_ids, inputs_embeds=inputs_embeds, image_features=image_embeds
            )
            inputs_embeds = inputs_embeds.masked_scatter(image_mask, image_embeds)

        if pixel_values_videos is not None:
            video_embeds, deepstack_video_embeds = self.get_video_features(pixel_values_videos, video_grid_thw)
            video_embeds = torch.cat(video_embeds, dim=0).to(inputs_embeds.device, inputs_embeds.dtype)
            _, video_mask = self.get_placeholder_mask(
                input_ids, inputs_embeds=inputs_embeds, video_features=video_embeds
            )
            inputs_embeds = inputs_embeds.masked_scatter(video_mask, video_embeds)

        visual_pos_masks = None
        deepstack_visual_embeds = None
        if image_mask is not None and video_mask is not None:
            # aggregate visual_pos_masks and deepstack_visual_embeds
            image_mask = image_mask[..., 0]
            video_mask = video_mask[..., 0]
            visual_pos_masks = image_mask | video_mask
            deepstack_visual_embeds = []
            image_mask_joint = image_mask[visual_pos_masks]
            video_mask_joint = video_mask[visual_pos_masks]
            for img_embed, vid_embed in zip(deepstack_image_embeds, deepstack_video_embeds):
                embed_joint = img_embed.new_zeros(visual_pos_masks.sum(), img_embed.shape[-1]).to(img_embed.device)
                embed_joint[image_mask_joint, :] = img_embed
                embed_joint[video_mask_joint, :] = vid_embed
                deepstack_visual_embeds.append(embed_joint)
        elif image_mask is not None:
            image_mask = image_mask[..., 0]
            visual_pos_masks = image_mask
            deepstack_visual_embeds = deepstack_image_embeds
        elif video_mask is not None:
            video_mask = video_mask[..., 0]
            visual_pos_masks = video_mask
            deepstack_visual_embeds = deepstack_video_embeds

        if position_ids is None:
            attention_mask_tensor = (
                attention_mask if not isinstance(attention_mask, dict) else attention_mask["full_attention"]
            )
            if attention_mask_tensor is not None and attention_mask_tensor.ndim == 4:
                attention_mask_tensor = torch.diagonal(attention_mask_tensor[:, 0], dim1=1, dim2=2)
                # Only apply conversion for floating point tensors (inverted masks)
                if attention_mask_tensor.dtype.is_floating_point:
                    attention_mask_tensor = attention_mask_tensor / torch.finfo(attention_mask_tensor.dtype).min
                    attention_mask_tensor = (1.0 - attention_mask_tensor).int()

            # Calculate RoPE index once per generation in the pre-fill stage only.
            # When compiling, we can't check tensor values thus we check only input length
            # It is safe to assume that `length!=1` means we're in pre-fill because compiled
            # models currently cannot do asssisted decoding
            prefill_compiled_stage = is_torchdynamo_compiling() and (
                (input_ids is not None and input_ids.shape[1] != 1)
                or (inputs_embeds is not None and inputs_embeds.shape[1] != 1)
            )
            prefill_noncompiled_stage = not is_torchdynamo_compiling() and (
                (cache_position is not None and cache_position[0] == 0)
                or (past_key_values is None or past_key_values.get_seq_length() == 0)
            )
            if (prefill_compiled_stage or prefill_noncompiled_stage) or self.rope_deltas is None:
                position_ids, rope_deltas = self.get_rope_index(
                    input_ids,
                    image_grid_thw,
                    video_grid_thw,
                    attention_mask=attention_mask_tensor,
                )
                self.rope_deltas = rope_deltas
            # then use the prev pre-calculated rope-deltas to get the correct position ids
            else:
                batch_size, seq_length, _ = inputs_embeds.shape
                delta = (
                    (cache_position[0] + self.rope_deltas).to(inputs_embeds.device)
                    if cache_position is not None
                    else 0
                )
                position_ids = torch.arange(seq_length, device=inputs_embeds.device)
                position_ids = position_ids.view(1, -1).expand(batch_size, -1)
                if cache_position is not None:  # otherwise `deltas` is an int `0`
                    delta = delta.repeat_interleave(batch_size // delta.shape[0], dim=0)
                position_ids = position_ids.add(delta)
                position_ids = position_ids.unsqueeze(0).expand(3, -1, -1)

        outputs = self.language_model(
            input_ids=None,
            position_ids=position_ids,
            attention_mask=attention_mask,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            cache_position=cache_position,
            visual_pos_masks=visual_pos_masks,
            deepstack_visual_embeds=deepstack_visual_embeds,
            # use_cache=use_cache,
            **kwargs,
        )

        return Qwen3VLModelOutputWithPast(
            last_hidden_state=outputs.last_hidden_state,
            past_key_values=outputs.past_key_values,
            rope_deltas=self.rope_deltas,
        )


@dataclass
@auto_docstring(
    custom_intro="""
    Base class for Qwen3VL causal language model (or autoregressive) outputs.
    """
)
class Qwen3VLCausalLMOutputWithPast(ModelOutput):
    r"""
    loss (`torch.FloatTensor` of shape `(1,)`, *optional*, returned when `labels` is provided):
        Language modeling loss (for next-token prediction).
    logits (`torch.FloatTensor` of shape `(batch_size, sequence_length, config.vocab_size)`):
        Prediction scores of the language modeling head (scores for each vocabulary token before SoftMax).
    past_key_values (`Cache`, *optional*, returned when `use_cache=True` is passed or when `config.use_cache=True`):
        It is a [`~cache_utils.Cache`] instance. For more details, see our [kv cache guide](https://huggingface.co/docs/transformers/en/kv_cache).

        Contains pre-computed hidden-states (key and values in the self-attention blocks) that can be used (see
        `past_key_values` input) to speed up sequential decoding.
    rope_deltas (`torch.LongTensor` of shape `(batch_size, )`, *optional*):
        The rope index difference between sequence length and multimodal rope.
    """

    loss: Optional[torch.FloatTensor] = None
    logits: Optional[torch.FloatTensor] = None
    past_key_values: Optional[Cache] = None
    hidden_states: Optional[tuple[torch.FloatTensor]] = None
    attentions: Optional[tuple[torch.FloatTensor]] = None
    rope_deltas: Optional[torch.LongTensor] = None
    k_logits: Optional[torch.FloatTensor] = None
    predicted_k: Optional[torch.LongTensor] = None

class LowRankProjector(nn.Module):
    def __init__(self, input_dim, output_dim, rank=64):
        super(LowRankProjector, self).__init__()
        self.rank = rank
        self.U = nn.Parameter(torch.randn(input_dim, rank))
        self.V = nn.Parameter(torch.randn(rank, output_dim))

    def forward(self, x):
        return torch.matmul(torch.matmul(x, self.U), self.V)

def extract_think_content_robust(input_ids, think_token_id=151667, end_think_token_id=151668, answer_token_id=9217):

    ids_list = input_ids.tolist() if isinstance(input_ids, torch.Tensor) else input_ids
    # find <think> token from back
    think_start_pos = -1
    for i in range(len(ids_list)-1, -1, -1):
        if ids_list[i] == think_token_id:
            think_start_pos = i
            break
    
    if think_start_pos == -1:
        raise ValueError(f"Unable to find <think> in input_ids")
    
    # Find the first '/think' beginning from 'think_start_pos'
    think_end_pos = -1
    for i in range(think_start_pos + 1, len(ids_list)):
        if ids_list[i] == end_think_token_id:
            think_end_pos = i
            break
    
    if think_end_pos == -1:
        raise ValueError(f"Unable to find </think> in input_ids")
    
    # find <\answer> token from back
    # as qwen3-vl doesn't explicitly encode the <answer> and </answer> tokens, we have to find them based on the 'answer' token
    answer_end_pos = -1
    for i in range(len(ids_list)-1, -1, -1):
        if ids_list[i] == answer_token_id:
            answer_end_pos = i+1 # add the '>' token
            break
    
    if answer_end_pos == -1:
        raise ValueError(f"Unable to find </answer> in input_ids")
    
    # answer_start_pos is the subsquent 2 token of </think> 
    answer_start_pos = think_end_pos + 2 # start from '<' for '<answer>'
    
    # extract CoT thoughts
    question_ids = ids_list[:think_start_pos] # not contain <think>
    content_ids = ids_list[think_start_pos+1:think_end_pos] # not contain <think> and </think>
    answer_ids = ids_list[answer_start_pos:answer_end_pos+4] # contain <answer> and </answer></im_end>\n<|endoftext>
    
    device = input_ids.device
    id_type = input_ids.dtype 
    return torch.tensor(question_ids, device=device, dtype=id_type), torch.tensor(content_ids, device=device, dtype=id_type), torch.tensor(answer_ids, device=device, dtype=id_type)

def split_cot_by_dynamic_boundaries(
    cot_ids: torch.Tensor,
    num_steps: int,
    eos_token_id: int,
    boundary_token_ids: set[int],
    min_step_tokens: int = 8,
):
    if num_steps <= 0:
        return [], []

    total_len = cot_ids.shape[0]
    if total_len == 0:
        eos = torch.tensor([eos_token_id], device=cot_ids.device, dtype=cot_ids.dtype)
        return [eos.clone() for _ in range(num_steps)], [1 for _ in range(num_steps)]

    boundaries = [
        idx + 1
        for idx, token_id in enumerate(cot_ids.tolist())
        if token_id in boundary_token_ids and idx + 1 < total_len
    ]
    split_points = [0]
    start = 0

    for step_idx in range(1, num_steps):
        remaining_steps = num_steps - step_idx
        remaining_tokens = total_len - start
        dynamic_min_tokens = min(min_step_tokens, max(1, remaining_tokens // (remaining_steps + 1)))
        lower = min(total_len, start + dynamic_min_tokens)
        upper = max(lower, total_len - remaining_steps * dynamic_min_tokens)
        target = round(total_len * step_idx / num_steps)
        target = min(max(target, lower), upper)

        candidates = [pos for pos in boundaries if lower <= pos <= upper]
        if candidates:
            split_at = min(candidates, key=lambda pos: (abs(pos - target), pos))
        else:
            split_at = target

        if split_at <= start:
            split_at = min(total_len, start + 1)
        split_points.append(split_at)
        start = split_at

    split_points.append(total_len)

    cot_step_id_list = []
    cot_step_len_list = []
    eos = torch.tensor([eos_token_id], device=cot_ids.device, dtype=cot_ids.dtype)
    for start, end in zip(split_points[:-1], split_points[1:]):
        step_ids = torch.concat([cot_ids[start:end], eos], 0)
        cot_step_id_list.append(step_ids)
        cot_step_len_list.append(end - start + 1)

    return cot_step_id_list, cot_step_len_list

def pad_input_ids_by_position(input_ids_list, pad_token_id, max_len=None, device="cuda"):
    """
    Extract input ids from nested list by position, pad each position group to the same length,
    convert to PyTorch Tensor, and return a list of tensors ordered by position.
    
    Args:
        input_ids_list: Nested list in format list[List[Tensor]], where each Tensor is a 1D sequence 
                        of token ids with variable length.
                        Example: [[tensor1_1, tensor1_2], [tensor2_1, tensor2_2], ...]
        pad_token_id: Token id used for padding (usually tokenizer.pad_token_id)
        max_len: Optional, specify target length for padding. If None, automatically use the maximum 
                 length of all samples in the corresponding position.
    
    Returns:
        list[torch.Tensor]: List of tensors ordered by position, each tensor has shape [batch_size, max_seq_len]
                            Example: [padded_tensor_for_position_1, padded_tensor_for_position_2, ...]
    """
    # Step 1: Validate input structure - ensure all sublists have the same length (same number of positions per sample)
    if not input_ids_list:
        return []
    position_num = len(input_ids_list[0])
    for sublist in input_ids_list:
        if len(sublist) != position_num:
            raise ValueError(f"All sublists must have the same length. First sublist has length {position_num}, "
                             f"but found sublist with length {len(sublist)}")
    
    # Step 2: Group tensors by their position index
    position_groups = []
    for pos in range(position_num):
        # Extract the pos-th Tensor from each sample
        pos_tensors = [sublist[pos] for sublist in input_ids_list]
        position_groups.append(pos_tensors)
    
    # Step 3: Pad each position group and convert to Tensor
    result_list = []
    for pos_group in position_groups:
        # Convert tensors to lists for easier processing
        pos_ids = []
        for tensor in pos_group:
            # Ensure each tensor is 1-dimensional (valid token id sequence)
            if tensor.dim() != 1:
                raise ValueError(f"Each token id sequence must be a 1D Tensor, but received Tensor with dimension {tensor.dim()}")
            pos_ids.append(tensor.tolist())
        
        # Determine target padding length for current position
        if max_len is None:
            # Automatically use the maximum length of all samples in current position
            pos_max_len = max(len(ids) for ids in pos_ids) if pos_ids else 0
        else:
            # Use specified max length, truncate sequences longer than max_len
            pos_max_len = max_len
            pos_ids = [ids[:pos_max_len] for ids in pos_ids]
        
        # Perform right-padding (standard in NLP tasks)
        padded_pos = []
        for ids in pos_ids:
            pad_length = pos_max_len - len(ids)
            padded_seq = ids + [pad_token_id] * pad_length
            padded_pos.append(padded_seq)
        
        # Convert padded list to PyTorch LongTensor (standard for token ids)
        pos_tensor = torch.tensor(padded_pos, dtype=torch.long, device=device)
        result_list.append(pos_tensor)
    
    return result_list


def _compute_colt_forward_cot_loss(loss_function, ref_logits, ref_labels, vocab_size, has_targets=True):
    """Apply the causal LM loss exactly once to the full latent-prefix sequence."""
    if not has_targets:
        return ref_logits.sum() * 0.0
    return loss_function(logits=ref_logits, labels=ref_labels, vocab_size=vocab_size)


def _compute_colt_backward_alignment_loss(cot_hidden, latent_embd, projector, probe_positions=None):
    """Align the latent state to the official fixed textual semantic anchor."""
    if probe_positions is None:
        cot_last_hidden = cot_hidden[:, -1, :]
    else:
        batch_indices = torch.arange(cot_hidden.shape[0], device=cot_hidden.device)
        cot_last_hidden = cot_hidden[batch_indices, probe_positions]
    cot_last_hidden = cot_last_hidden.detach()
    cot_to_latent = projector(cot_last_hidden).unsqueeze(1).to(latent_embd.dtype)
    return 1 - F.cosine_similarity(cot_to_latent.float(), latent_embd.float(), dim=-1).mean()


def _ensure_colt_decoder_initialized(
    decoder,
    already_checked,
    name_or_path,
    torch_dtype,
    device,
    enable_gradient_checkpointing=False,
    loader=None,
):
    """Check a nested decoder at most once and reload it if its embedding is all zero."""
    if decoder is None or already_checked:
        return decoder, already_checked

    # Set this before any CUDA reduction or reload so failures cannot repeat the scan.
    already_checked = True
    try:
        emb_w = decoder.get_input_embeddings().weight
        if emb_w is None or emb_w.numel() == 0 or emb_w.detach().abs().sum().item() != 0.0:
            return decoder, already_checked

        load_model = loader or AutoModelForCausalLM.from_pretrained
        decoder = load_model(name_or_path, torch_dtype=torch_dtype, resume_download=True).to(device)
        if enable_gradient_checkpointing:
            decoder.gradient_checkpointing_enable()
    except Exception:
        # Preserve the original non-fatal behavior, but never rescan on a later microbatch.
        pass
    return decoder, already_checked


def _pad_colt_sequence(tensor, target_length, value=0):
    pad_length = target_length - tensor.shape[1]
    if pad_length <= 0:
        return tensor
    if tensor.ndim == 2:
        return F.pad(tensor, (0, pad_length), value=value)
    if tensor.ndim == 3:
        return F.pad(tensor, (0, 0, 0, pad_length), value=value)
    raise ValueError(f"Expected a rank-2 or rank-3 sequence tensor, got shape {tuple(tensor.shape)}")


def _run_colt_forward_decoder_steps(decoder, projector, loss_function, records, vocab_size, batched):
    """Run latent-to-CoT supervision while preserving equal weighting across latent steps."""
    if not records:
        return []

    if not batched:
        losses = []
        for record in records:
            outputs = decoder(
                inputs_embeds=record["inputs_embeds"],
                attention_mask=record["attention_mask"],
                position_ids=record["position_ids"],
                use_cache=False,
            )
            logits = projector(outputs.logits)
            losses.append(
                _compute_colt_forward_cot_loss(
                    loss_function,
                    logits,
                    record["labels"],
                    vocab_size,
                    has_targets=record["has_targets"],
                )
            )
        return losses

    max_length = max(record["inputs_embeds"].shape[1] for record in records)
    batch_sizes = [record["inputs_embeds"].shape[0] for record in records]
    inputs_embeds = torch.cat(
        [_pad_colt_sequence(record["inputs_embeds"], max_length) for record in records], dim=0
    )
    attention_mask = torch.cat(
        [_pad_colt_sequence(record["attention_mask"], max_length) for record in records], dim=0
    )
    position_ids = torch.cat(
        [_pad_colt_sequence(record["position_ids"], max_length) for record in records], dim=0
    )
    outputs = decoder(
        inputs_embeds=inputs_embeds,
        attention_mask=attention_mask,
        position_ids=position_ids,
        use_cache=False,
    )
    step_logits = outputs.logits.split(batch_sizes, dim=0)

    losses = []
    for logits, record in zip(step_logits, records):
        original_length = record["inputs_embeds"].shape[1]
        logits = projector(logits[:, :original_length])
        losses.append(
            _compute_colt_forward_cot_loss(
                loss_function,
                logits,
                record["labels"],
                vocab_size,
                has_targets=record["has_targets"],
            )
        )
    return losses


def _get_colt_decoder_backbone(decoder):
    return decoder.get_decoder() if hasattr(decoder, "get_decoder") else getattr(decoder, "model", None)


def _run_colt_backward_decoder_steps(decoder, projector, records, pad_token_id, batched):
    """Run CoT-to-latent supervision and select each step's original probe position."""
    if not records:
        return []

    decoder_backbone = _get_colt_decoder_backbone(decoder)

    def run_backbone(input_ids, attention_mask):
        if decoder_backbone is not None:
            return decoder_backbone(input_ids=input_ids, attention_mask=attention_mask, use_cache=False)[0]
        outputs = decoder(
            input_ids=input_ids,
            attention_mask=attention_mask,
            use_cache=False,
            output_hidden_states=True,
        )
        return outputs.hidden_states[-1]

    if not batched:
        losses = []
        for record in records:
            hidden = run_backbone(record["input_ids"], record["attention_mask"])
            loss = _compute_colt_backward_alignment_loss(
                hidden,
                record["latent_embd"],
                projector,
                probe_positions=record["probe_positions"],
            )
            losses.append(loss if record.get("active", True) else loss * 0.0)
        return losses

    max_length = max(record["input_ids"].shape[1] for record in records)
    batch_sizes = [record["input_ids"].shape[0] for record in records]
    input_ids = torch.cat(
        [_pad_colt_sequence(record["input_ids"], max_length, value=pad_token_id) for record in records], dim=0
    )
    attention_mask = torch.cat(
        [_pad_colt_sequence(record["attention_mask"], max_length) for record in records], dim=0
    )
    hidden_steps = run_backbone(input_ids, attention_mask).split(batch_sizes, dim=0)

    losses = []
    for hidden, record in zip(hidden_steps, records):
        loss = _compute_colt_backward_alignment_loss(
            hidden,
            record["latent_embd"],
            projector,
            probe_positions=record["probe_positions"],
        )
        losses.append(loss if record.get("active", True) else loss * 0.0)
    return losses


def _is_colt_paper_faithful_enabled():
    return os.environ.get("COLT_PAPER_FAITHFUL", "0").strip().lower() in {"1", "true", "yes", "on"}


def _is_colt_aux_batching_enabled():
    return os.environ.get("COLT_BATCH_AUX_DECODERS", "0").strip().lower() in {"1", "true", "yes", "on"}


def _is_colt_rank_zero():
    if torch.distributed.is_available() and torch.distributed.is_initialized():
        return torch.distributed.get_rank() == 0
    return int(os.environ.get("RANK", "0")) == 0


def _synchronize_colt_oracle_k(local_k, device):
    """Return the largest GT K so ZeRO-3 ranks execute identical module calls."""
    if not (torch.distributed.is_available() and torch.distributed.is_initialized()):
        return local_k
    synchronized_k = torch.tensor(local_k, dtype=torch.long, device=device)
    torch.distributed.all_reduce(synchronized_k, op=torch.distributed.ReduceOp.MAX)
    return int(synchronized_k.item())


def _colt_component_log_interval():
    try:
        return max(int(os.environ.get("COLT_COMPONENT_LOG_EVERY", "8")), 0)
    except ValueError:
        return 8


class Qwen3VLForConditionalGeneration(Qwen3VLPreTrainedModel, GenerationMixin):
    _checkpoint_conversion_mapping = {}
    _tied_weights_keys = ["lm_head.weight"]
    # Reference: fix gemma3 grad acc #37208
    accepts_loss_kwargs = False
    config: Qwen3VLConfig

    def __init__(self, config):
        super().__init__(config)
        self.model = Qwen3VLModel(config)
        self.lm_head = nn.Linear(config.text_config.hidden_size, config.text_config.vocab_size, bias=False)
        self.paper_faithful = _is_colt_paper_faithful_enabled()
        self.batch_aux_decoders = self.paper_faithful and _is_colt_aux_batching_enabled()
        self._colt_forward_microbatch_count = 0
        oracle_k_settings = resolve_oracle_k_settings(config)
        self.oracle_k_enabled = oracle_k_settings.enabled
        self.oracle_k_max = oracle_k_settings.max_k
        self.oracle_k_budget_conditioning = oracle_k_settings.budget_conditioning
        self.oracle_k_predictor_enabled = oracle_k_settings.predictor_enabled
        self.oracle_k_predictor_loss_weight = oracle_k_settings.predictor_loss_weight
        self.oracle_k_dynamic_inference = oracle_k_settings.dynamic_inference
        self.last_oracle_k_prediction = None
        self.last_oracle_k_used = None
        self._oracle_k_predictor_preflight_done = False
        self._oracle_k_first_batch_logged = False
        self._oracle_k_metric_loss_sum = None
        self._oracle_k_metric_correct = None
        self._oracle_k_metric_count = None
        if self.oracle_k_enabled and self.oracle_k_predictor_enabled:
            self.oracle_k_predictor = OracleKPredictor(
                self.oracle_k_max,
                config.text_config.hidden_size,
            )
        else:
            self.oracle_k_predictor = None
        # NOTE: When training under some sharding/initialization contexts (e.g. init_empty_weights / ZeRO init),
        # loading a nested decoder inside __init__ can silently produce zero/empty parameters.
        # We still initialize here, but also support lazy re-loading in forward if we detect zeroed weights.
        self.latent_reasoning_mode = os.environ.get("COLT_DISABLE_LATENT_REASONING", "0") != "1"
        if not self.latent_reasoning_mode:
            self.post_init()
            return
        self.decoder = None
        self.backward_decoder = None
        self._decoder_name_or_path = os.environ.get("COLT_DECODER_MODEL_PATH", "Qwen/Qwen3-0.6B")
        if self.training:
            self.decoder = AutoModelForCausalLM.from_pretrained(
                self._decoder_name_or_path,
                torch_dtype=config.text_config.dtype,
                resume_download=True,
            )
            self.backward_decoder = AutoModelForCausalLM.from_pretrained(
                self._decoder_name_or_path,
                torch_dtype=config.text_config.dtype,
                resume_download=True,
            )
        self._decoder_reload_attempted = False
        self._backward_decoder_reload_attempted = False
        
        if self.decoder is not None:
            if self.lm_head.in_features == self.decoder.lm_head.in_features:
                self.pj_in = nn.Identity()
                self.pj_back = nn.Identity()
            else:
                self.pj_in = nn.Sequential(nn.Linear(self.lm_head.in_features, self.decoder.lm_head.in_features), nn.LayerNorm(self.decoder.lm_head.in_features),)
                self.pj_back = nn.Sequential(
                    nn.Linear(self.decoder.lm_head.in_features, self.lm_head.in_features),
                    nn.LayerNorm(self.lm_head.in_features),
                )
            input_dim = self.decoder.lm_head.out_features
            output_dim = self.lm_head.out_features
            if input_dim == output_dim:
                self.pj_out = nn.Identity()
            else:
                self.pj_out = LowRankProjector(input_dim, output_dim, rank=input_dim // 4)
        else:
            self.pj_in = nn.Identity()
            self.pj_out = nn.Identity()
            self.pj_back = nn.Identity()

        self.num_latent = 3
        if self.oracle_k_enabled and self.oracle_k_budget_conditioning:
            self.oracle_k_conditioner = OracleKBudgetConditioner(
                self.oracle_k_max,
                config.text_config.hidden_size,
            )
        else:
            self.oracle_k_conditioner = None
        self.prj = nn.Sequential(
                nn.Dropout(0.0),
                nn.Linear(config.text_config.hidden_size, config.text_config.hidden_size//2),
                nn.GELU(),
                nn.Linear(config.text_config.hidden_size//2, config.text_config.hidden_size),
                nn.LayerNorm(config.text_config.hidden_size),
            )
        self.backward_align_weight = 0.2
        self.forward_align_weight = 0.2
        self.prediction_weight = 0.2
        self.latent_predictor = nn.Sequential(
            nn.Linear(config.text_config.hidden_size, config.text_config.hidden_size),
            nn.GELU(),
            nn.Linear(config.text_config.hidden_size, config.text_config.hidden_size),
            nn.LayerNorm(config.text_config.hidden_size),
        )
        # Latent hidden states after LayerNorm typically have std~1, while token embeddings are much smaller.
        # Without scaling, fp16/bf16 attention can overflow and produce NaNs in early decoder layers.
        self.latent_to_decoder_scale = nn.Parameter(torch.tensor(0.02, dtype=torch.float32))
        self.alpha = nn.Parameter(torch.tensor(0.1, dtype=torch.float32))

        tokenizer = AutoTokenizer.from_pretrained(self._decoder_name_or_path)
        self.think_token_id = tokenizer.encode("<think>", add_special_tokens=False)[0]
        self.end_think_token_id = tokenizer.encode("</think>", add_special_tokens=False)[0]
        self.answer_token_id = tokenizer.encode("answer", add_special_tokens=False)[0]
        self.pad_token_id = tokenizer.pad_token_id if tokenizer.pad_token_id is not None else tokenizer.eos_token_id
        self.eos_token_id = tokenizer.encode(tokenizer.eos_token, add_special_tokens=False)[0]
        cot_boundary_texts = ["\n", "\n\n", ".", "。", "?", "？", "!", "！", ";", "；", ":", "：", ",", "，"]
        self.cot_boundary_token_ids = {
            token_id
            for text in cot_boundary_texts
            for token_id in tokenizer.encode(text, add_special_tokens=False)
        }
        self.post_init()
        if self.training and self.decoder is not None:
            self.decoder.gradient_checkpointing_enable()
        self.tokenizer = tokenizer

    def _parse_oracle_k_steps(self, cot_ids):
        cot_text = self.tokenizer.decode(
            cot_ids.tolist(),
            skip_special_tokens=False,
            clean_up_tokenization_spaces=False,
        )
        annotation = parse_oracle_k_cot(cot_text, min_k=1, max_k=self.oracle_k_max)
        eos = torch.tensor([self.eos_token_id], device=cot_ids.device, dtype=cot_ids.dtype)
        step_ids = []
        step_lens = []
        for block in annotation.blocks:
            block_ids = torch.tensor(
                self.tokenizer.encode(block, add_special_tokens=False),
                device=cot_ids.device,
                dtype=cot_ids.dtype,
            )
            block_with_eos = torch.cat([block_ids, eos], dim=0)
            step_ids.append(block_with_eos)
            step_lens.append(block_with_eos.shape[0])
        return annotation.k, step_ids, step_lens

    def _condition_latent_with_oracle_k(self, latent_embd, oracle_k, step_index):
        if not self.oracle_k_enabled or not self.oracle_k_budget_conditioning:
            return latent_embd
        return self.oracle_k_conditioner(latent_embd, oracle_k, step_index)

    def _pool_question_hidden(self, hidden_states, attention_mask):
        return pool_last_valid_hidden(hidden_states, attention_mask)

    def _predict_oracle_k(self, hidden_states, attention_mask):
        if self.oracle_k_predictor is None:
            return None
        self._prepare_oracle_k_predictor()
        pooled_hidden = self._pool_question_hidden(hidden_states, attention_mask)
        return self.oracle_k_predictor(pooled_hidden)

    @staticmethod
    def _oracle_k_flag(name, default="0"):
        return os.environ.get(name, default).strip().lower() in {"1", "true", "yes", "on"}

    @staticmethod
    def _oracle_k_parameter_stats(name, parameter):
        values = parameter.detach().float()
        finite = torch.isfinite(values)
        finite_values = values[finite]
        stats = {
            "name": name,
            "shape": list(values.shape),
            "numel": values.numel(),
            "nonfinite": int((~finite).sum().item()),
        }
        if finite_values.numel() > 0:
            stats.update(
                mean=float(finite_values.mean().item()),
                std=float(finite_values.std(unbiased=False).item()),
                min=float(finite_values.min().item()),
                max=float(finite_values.max().item()),
                abs_max=float(finite_values.abs().max().item()),
            )
        return stats

    def _oracle_k_predictor_audit(self, phase):
        parameters = [
            self._oracle_k_parameter_stats(name, parameter)
            for name, parameter in self.oracle_k_predictor.named_parameters()
        ]
        output_weight = self.oracle_k_predictor.network[-1].weight.detach().float()
        pairwise = []
        for left in range(output_weight.shape[0]):
            for right in range(left + 1, output_weight.shape[0]):
                difference = (output_weight[left] - output_weight[right]).abs().max()
                pairwise.append(
                    {
                        "rows": [left + 1, right + 1],
                        "max_abs_diff": float(difference.item()),
                        "cosine": float(
                            F.cosine_similarity(output_weight[left], output_weight[right], dim=0).item()
                        ),
                    }
                )
        closest_rows = min(pairwise, key=lambda item: item["max_abs_diff"])
        row_norms = output_weight.norm(dim=1).cpu().tolist()
        print(
            "[oracle-k-predictor-audit] "
            + json.dumps(
                {
                    "phase": phase,
                    "parameters": parameters,
                    "output_row_norms": row_norms,
                    "closest_output_rows": closest_rows,
                    "exact_duplicate_output_rows": [
                        item["rows"] for item in pairwise if item["max_abs_diff"] == 0.0
                    ],
                },
                sort_keys=True,
            )
        )

    def _reset_oracle_k_predictor(self):
        initializer_range = float(getattr(self.config.get_text_config(), "initializer_range", 0.02))
        output_std = float(os.environ.get("COLT_ORACLE_K_PREDICTOR_OUTPUT_STD", "0.001"))
        seed = int(os.environ.get("COLT_ORACLE_K_PREDICTOR_INIT_SEED", "1234"))
        parameter = next(self.oracle_k_predictor.parameters())
        devices = [parameter.device.index] if parameter.is_cuda else []
        with torch.random.fork_rng(devices=devices):
            torch.manual_seed(seed)
            self.oracle_k_predictor.reset_parameters(initializer_range, output_std)

    def _prepare_oracle_k_predictor(self):
        if self._oracle_k_predictor_preflight_done or self.oracle_k_predictor is None:
            return

        initialize = self.training and self._oracle_k_flag("COLT_ORACLE_K_INITIALIZE_PREDICTOR")
        diagnostics = self._oracle_k_flag("COLT_ORACLE_K_DIAGNOSTICS")
        parameters = list(self.oracle_k_predictor.parameters())
        zero_partitioned = any(hasattr(parameter, "ds_id") for parameter in parameters)
        rank = torch.distributed.get_rank() if torch.distributed.is_initialized() else 0

        gathered_context = contextlib.nullcontext()
        if zero_partitioned:
            import deepspeed

            gathered_context = deepspeed.zero.GatheredParameters(
                parameters,
                modifier_rank=0 if initialize else None,
            )

        with gathered_context:
            if diagnostics and rank == 0:
                self._oracle_k_predictor_audit("loaded")
            if initialize and (zero_partitioned is False or rank == 0):
                self._reset_oracle_k_predictor()
            if diagnostics and initialize and rank == 0:
                self._oracle_k_predictor_audit("reset")

        if initialize and not zero_partitioned and torch.distributed.is_initialized():
            for parameter in parameters:
                torch.distributed.broadcast(parameter.data, src=0)

        self._oracle_k_predictor_preflight_done = True

    def _log_oracle_k_first_batch(self, k_logits, k_targets, predicted_k):
        if self._oracle_k_first_batch_logged:
            return
        diagnostics = self._oracle_k_flag("COLT_ORACLE_K_DIAGNOSTICS")
        strict = self._oracle_k_flag("COLT_ORACLE_K_STRICT_INITIALIZATION")
        if not diagnostics and not strict:
            self._oracle_k_first_batch_logged = True
            return

        local_loss_sum = F.cross_entropy(k_logits.float(), k_targets, reduction="sum").detach()
        local_count = torch.tensor(k_targets.numel(), dtype=torch.float32, device=k_logits.device)
        local_abs_max = k_logits.detach().float().abs().max()
        summary = torch.stack([local_loss_sum, local_count, local_abs_max])
        if torch.distributed.is_initialized():
            torch.distributed.all_reduce(summary[:2], op=torch.distributed.ReduceOp.SUM)
            torch.distributed.all_reduce(summary[2], op=torch.distributed.ReduceOp.MAX)
        global_loss = summary[0] / summary[1].clamp_min(1)

        gathered_logits = [k_logits.detach().float()]
        gathered_targets = [k_targets.detach()]
        gathered_predictions = [predicted_k.detach()]
        if torch.distributed.is_initialized():
            world_size = torch.distributed.get_world_size()
            gathered_logits = [torch.empty_like(gathered_logits[0]) for _ in range(world_size)]
            gathered_targets = [torch.empty_like(gathered_targets[0]) for _ in range(world_size)]
            gathered_predictions = [torch.empty_like(gathered_predictions[0]) for _ in range(world_size)]
            torch.distributed.all_gather(gathered_logits, k_logits.detach().float())
            torch.distributed.all_gather(gathered_targets, k_targets.detach())
            torch.distributed.all_gather(gathered_predictions, predicted_k.detach())

        if _is_colt_rank_zero() and diagnostics:
            records = []
            for rank, (rank_logits, rank_targets, rank_predictions) in enumerate(
                zip(gathered_logits, gathered_targets, gathered_predictions)
            ):
                for index in range(rank_targets.numel()):
                    records.append(
                        {
                            "rank": rank,
                            "sample": index,
                            "logits": rank_logits[index].cpu().tolist(),
                            "gt_k": int(rank_targets[index].item()) + 1,
                            "predicted_k": int(rank_predictions[index].item()),
                        }
                    )
            print(
                "[oracle-k-initial-batch] "
                + json.dumps(
                    {
                        "global_cross_entropy": float(global_loss.item()),
                        "global_abs_max_logit": float(summary[2].item()),
                        "records": records,
                    },
                    sort_keys=True,
                )
            )

        if strict:
            loss_value = float(global_loss.item())
            logit_abs_max = float(summary[2].item())
            if not (1.0 <= loss_value <= 4.0) or not (logit_abs_max <= 10.0):
                raise RuntimeError(
                    "Oracle-K predictor initialization failed: "
                    f"global CE={loss_value:.6g}, max_abs_logit={logit_abs_max:.6g}"
                )
        self._oracle_k_first_batch_logged = True

    def _accumulate_oracle_k_metrics(self, k_logits, k_targets, predicted_k):
        loss_sum = F.cross_entropy(k_logits.float(), k_targets, reduction="sum").detach()
        correct = (predicted_k == k_targets + 1).detach().float().sum()
        count = torch.tensor(k_targets.numel(), dtype=torch.float32, device=k_logits.device)
        if self._oracle_k_metric_loss_sum is None:
            self._oracle_k_metric_loss_sum = loss_sum
            self._oracle_k_metric_correct = correct
            self._oracle_k_metric_count = count
        else:
            self._oracle_k_metric_loss_sum += loss_sum
            self._oracle_k_metric_correct += correct
            self._oracle_k_metric_count += count

    def _flush_oracle_k_metrics(self):
        if self._oracle_k_metric_loss_sum is None:
            return None
        totals = torch.stack(
            [self._oracle_k_metric_loss_sum, self._oracle_k_metric_correct, self._oracle_k_metric_count]
        )
        if torch.distributed.is_initialized():
            torch.distributed.all_reduce(totals, op=torch.distributed.ReduceOp.SUM)
        self._oracle_k_metric_loss_sum = None
        self._oracle_k_metric_correct = None
        self._oracle_k_metric_count = None
        count = totals[2].clamp_min(1)
        return totals[0] / count, totals[1] / count, totals[2]

    def _resolve_latent_steps_for_inference(self, num_hidden_generations, predicted_k=None):
        if not self.oracle_k_enabled:
            return num_hidden_generations if num_hidden_generations > 0 else self.num_latent

        forced_k = None
        if num_hidden_generations <= 0:
            forced_k = resolve_forced_inference_k(self.oracle_k_max)
        predicted_k_value = None
        if predicted_k is not None:
            if (
                predicted_k.numel() != 1
                and self.oracle_k_dynamic_inference
                and num_hidden_generations <= 0
                and forced_k is None
            ):
                raise ValueError(
                    "Dynamic Oracle-K inference currently requires batch size 1; "
                    f"received {predicted_k.numel()} predicted K values"
                )
            if predicted_k.numel() == 1:
                predicted_k_value = int(predicted_k.reshape(-1)[0].item())
        return select_oracle_k_inference_steps(
            max_k=self.oracle_k_max,
            default_k=self.num_latent,
            num_hidden_generations=num_hidden_generations,
            forced_k=forced_k,
            predicted_k=predicted_k_value,
            dynamic_inference=self.oracle_k_dynamic_inference,
        )
        

    def get_input_embeddings(self):
        return self.model.get_input_embeddings()

    def set_input_embeddings(self, value):
        self.model.set_input_embeddings(value)

    def set_decoder(self, decoder):
        self.model.set_decoder(decoder)

    def get_decoder(self):
        return self.model.get_decoder()

    def get_video_features(
        self, pixel_values_videos: torch.FloatTensor, video_grid_thw: Optional[torch.LongTensor] = None
    ):
        return self.model.get_video_features(pixel_values_videos, video_grid_thw)

    def get_image_features(self, pixel_values: torch.FloatTensor, image_grid_thw: Optional[torch.LongTensor] = None):
        return self.model.get_image_features(pixel_values, image_grid_thw)

    # Make modules available through conditional class for BC
    @property
    def language_model(self):
        return self.model.language_model

    @property
    def visual(self):
        return self.model.visual

    @check_model_inputs
    def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        labels: Optional[torch.LongTensor] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        cache_position: Optional[torch.LongTensor] = None,
        logits_to_keep: Union[int, torch.Tensor] = 0,
        num_hidden_generations: int = 0,  # The num of generate latent states
        hidden_generation_mode: bool = False,  # enable latent model or not
        **kwargs: Unpack[TransformersKwargs],
    ) -> Union[tuple, Qwen3VLCausalLMOutputWithPast]:
        r"""
        labels (`torch.LongTensor` of shape `(batch_size, sequence_length)`, *optional*):
            Labels for computing the masked language modeling loss. Indices should either be in `[0, ...,
            config.vocab_size]` or -100 (see `input_ids` docstring). Tokens with indices set to `-100` are ignored
            (masked), the loss is only computed for the tokens with labels in `[0, ..., config.vocab_size]`.
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.

        Example:
            TODO: Add example
        """
        k_logits = None
        predicted_k = None
        if self.latent_reasoning_mode:
            # Prepare the inputs of each process
            # seperate the question, cot procedure and answer of each sample
            question_id_list, cot_id_list, answer_id_list = map(
                list,
                zip(*[
                    extract_think_content_robust(
                        input_ids_i,
                        self.think_token_id,
                        self.end_think_token_id,
                        self.answer_token_id,
                    )
                    for input_ids_i in input_ids
                ])
            )
            cot_step_id_list = []
            cot_step_len_list = []

            if self.oracle_k_enabled:
                if len(cot_id_list) != 1:
                    raise ValueError(
                        "Oracle-K training currently requires per-device batch size 1; "
                        f"received {len(cot_id_list)} samples"
                    )
                oracle_k, cot_step_id_list_i, cot_step_len_list_i = self._parse_oracle_k_steps(cot_id_list[0])
                cot_step_id_list.append(cot_step_id_list_i)
                cot_step_len_list.append(cot_step_len_list_i)
                training_latent_steps = oracle_k
            else:
                # Split CoT steps by nearby punctuation/newline boundaries instead of fixed equal chunks.
                for i in range(len(cot_id_list)):
                    num_steps = max(self.num_latent, 1)
                    cot_step_id_list_i, cot_step_len_list_i = split_cot_by_dynamic_boundaries(
                        cot_id_list[i],
                        num_steps=num_steps,
                        eos_token_id=self.eos_token_id,
                        boundary_token_ids=self.cot_boundary_token_ids,
                    )
                    cot_step_id_list.append(cot_step_id_list_i)
                    cot_step_len_list.append(cot_step_len_list_i)
                training_latent_steps = self.num_latent
            cot_step_id = pad_input_ids_by_position(cot_step_id_list, self.pad_token_id, device=input_ids.device)
            # Encode the question (right padding for alignment)
            question_ids = torch.nn.utils.rnn.pad_sequence(
                question_id_list, batch_first=True, padding_value=self.pad_token_id
            )
            attention_mask_question = (question_ids != self.pad_token_id).long()
            position_ids_question = None

            if hidden_generation_mode and labels is None:
                if self.oracle_k_enabled:
                    latent_steps = num_hidden_generations
                else:
                    latent_steps = num_hidden_generations if num_hidden_generations > 0 else self.num_latent
                latent_outputs = self._forward_latent_reasoning(
                    input_ids=question_ids,
                    attention_mask=attention_mask_question,
                    position_ids=position_ids_question,
                    pixel_values=pixel_values,
                    pixel_values_videos=pixel_values_videos,
                    image_grid_thw=image_grid_thw,
                    video_grid_thw=video_grid_thw,
                    num_hidden_generations=latent_steps,
                    **kwargs,
                )
                return latent_outputs

            # Some ZeRO initialization paths have produced zeroed nested decoders. Check once
            # on the real device, then never scan these large embedding matrices again.
            decoder_device = input_ids.device
            self.decoder, self._decoder_reload_attempted = _ensure_colt_decoder_initialized(
                self.decoder,
                self._decoder_reload_attempted,
                self._decoder_name_or_path,
                self.config.text_config.dtype,
                decoder_device,
            )
            self.backward_decoder, self._backward_decoder_reload_attempted = _ensure_colt_decoder_initialized(
                self.backward_decoder,
                self._backward_decoder_reload_attempted,
                self._decoder_name_or_path,
                self.config.text_config.dtype,
                decoder_device,
            )

            past_key_values = DynamicCache(config=self.config.text_config)
            outputs = self.model(
                input_ids=question_ids,
                pixel_values=pixel_values,
                pixel_values_videos=pixel_values_videos,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                position_ids=position_ids_question,
                attention_mask=attention_mask_question,
                past_key_values=past_key_values,
                inputs_embeds=None,
                **kwargs,
            )

            hidden_states = outputs[0]
            latent_embd = hidden_states[:, -1:, :]
            current_seq_len = outputs.past_key_values.get_seq_length()
            if self.oracle_k_predictor_enabled:
                k_logits = self._predict_oracle_k(hidden_states, attention_mask_question)
                predicted_k = torch.argmax(k_logits.detach(), dim=-1) + 1
                k_targets = torch.full(
                    (hidden_states.shape[0],),
                    oracle_k - 1,
                    dtype=torch.long,
                    device=k_logits.device,
                )
                k_loss_total = F.cross_entropy(k_logits.float(), k_targets)
                k_accuracy = (predicted_k == k_targets + 1).float().mean()
                self._log_oracle_k_first_batch(k_logits, k_targets, predicted_k)
                self._accumulate_oracle_k_metrics(k_logits, k_targets, predicted_k)
            else:
                k_loss_total = hidden_states.new_zeros(())
                k_accuracy = hidden_states.new_zeros(())

            # Loss buckets for three training objectives:
            # 1) forward_loss_total: latent -> CoT step decoding loss
            # 2) backward_loss_total: CoT step -> latent alignment loss
            # 3) prediction_loss_total: latent_t -> latent_{t+1} prediction loss
            # 4) ce_loss_total: final answer decoding loss
            forward_loss_total = 0.0
            backward_loss_total = 0.0
            prediction_loss_total = 0.0
            ce_loss_total = 0.0
            forward_steps_num = 0
            backward_steps_num = 0
            prediction_steps_num = 0
            batch_size = hidden_states.shape[0]
            batched_forward_records = []
            batched_backward_records = []

            synchronized_latent_steps = (
                _synchronize_colt_oracle_k(training_latent_steps, input_ids.device)
                if self.oracle_k_enabled
                else training_latent_steps
            )
            oracle_k_plan = (
                build_oracle_k_training_plan(training_latent_steps, synchronized_latent_steps)
                if self.oracle_k_enabled
                else None
            )
            if synchronized_latent_steps != 0:
                for i in range(synchronized_latent_steps):
                    active_step = oracle_k_plan[i].active if oracle_k_plan is not None else True
                    # ---------------------------
                    # A) latent transition step
                    # ---------------------------
                    # For RoPE index / causal mask, attention_mask should reflect the full (cached + current) length.
                    step_attention_mask = torch.ones((batch_size,  1), dtype=torch.long, device=latent_embd.device)
                    latent_step_input = self._condition_latent_with_oracle_k(
                        latent_embd,
                        training_latent_steps,
                        min(i + 1, training_latent_steps),
                    )
                    current_latent_embd = latent_step_input
                    if active_step:
                        step_cache_position = torch.arange(
                            current_seq_len + i,
                            current_seq_len + i + 1,
                            device=latent_embd.device,
                        )
                        outputs = self.model(
                            inputs_embeds=latent_step_input,
                            past_key_values=past_key_values,
                            cache_position=step_cache_position,
                            attention_mask=step_attention_mask,
                            position_ids=None,
                            **kwargs,
                        )
                        past_key_values = outputs.past_key_values
                    else:
                        # Keep ZeRO-3 module/gradient-hook ordering identical without
                        # advancing the real latent state or its local-K KV cache.
                        dummy_cache = DynamicCache(config=self.config.text_config)
                        outputs = self.model(
                            inputs_embeds=latent_step_input,
                            past_key_values=dummy_cache,
                            cache_position=torch.arange(1, device=latent_embd.device),
                            attention_mask=step_attention_mask,
                            position_ids=None,
                            **kwargs,
                        )
                    hidden_states = outputs[0]
                    next_latent_embd = hidden_states[:, -1:, :] + self.alpha * self.prj(hidden_states[:, -1:, :])
                    pred_next_latent = self.latent_predictor(current_latent_embd.to(next_latent_embd.dtype))
                    prediction_loss = F.mse_loss(pred_next_latent, next_latent_embd.detach())
                    prediction_loss_total += prediction_loss if active_step else prediction_loss * 0.0
                    if active_step:
                        prediction_steps_num += 1

                    # -----------------------------------------------
                    # B) forward supervision: latent -> CoT decoding
                    # -----------------------------------------------
                    if active_step:
                        latent_embd = next_latent_embd
                    supervised_latent_embd = latent_embd if active_step else next_latent_embd
                    step_ref_idx = oracle_k_plan[i].forward_index if oracle_k_plan is not None else i
                    decoder_embeddings = self.decoder.get_input_embeddings()
                    decoder_embed_dtype = decoder_embeddings.weight.dtype
                    cot_step_embed = decoder_embeddings(cot_step_id[step_ref_idx]).to(decoder_embed_dtype)
                    latent_for_ref = self.pj_in(supervised_latent_embd) * self.latent_to_decoder_scale.to(
                        supervised_latent_embd.device, supervised_latent_embd.dtype
                    )
                    latent_for_ref = latent_for_ref.to(decoder_embed_dtype)
                    ref_embds = torch.concat([latent_for_ref, cot_step_embed], dim=1)
                    
                    current_ref_ids = cot_step_id[step_ref_idx]
                    current_ref_lens_cpu = [cot_step_len_list[b][step_ref_idx] for b in range(batch_size)]
                    has_forward_targets = active_step and any(length > 0 for length in current_ref_lens_cpu)
                    current_ref_lens = torch.tensor(
                        current_ref_lens_cpu,
                        dtype=torch.long,
                        device=current_ref_ids.device,
                    )
                    current_ref_valid = (
                        torch.arange(current_ref_ids.shape[1], device=current_ref_ids.device)
                        .unsqueeze(0)
                        .expand(batch_size, -1)
                        < current_ref_lens.unsqueeze(1)
                    )
                    if not active_step:
                        current_ref_valid = torch.zeros_like(current_ref_valid)
                    prefix_mask = torch.ones((batch_size, 1), dtype=torch.long, device=current_ref_ids.device)
                    ref_attention_mask = torch.cat([prefix_mask, current_ref_valid.long()], dim=1)
                    ref_labels = current_ref_ids.masked_fill(~current_ref_valid, -100)
                    ref_labels = torch.cat(
                        [
                            torch.full((batch_size, 1), -100, dtype=ref_labels.dtype, device=ref_labels.device),
                            ref_labels,
                        ],
                        dim=1,
                    )

                    ref_position_ids = (
                        torch.arange(ref_embds.shape[1], device=ref_embds.device, dtype=torch.long)
                        .unsqueeze(0)
                        .expand(batch_size, -1)
                    )
                    forward_record = {
                        "inputs_embeds": ref_embds,
                        "attention_mask": ref_attention_mask,
                        "position_ids": ref_position_ids,
                        "labels": ref_labels,
                        "has_targets": has_forward_targets,
                    }
                    if self.batch_aux_decoders:
                        batched_forward_records.append(forward_record)
                    else:
                        ref_outputs = self.decoder(
                            inputs_embeds=ref_embds,
                            attention_mask=ref_attention_mask,
                            position_ids=ref_position_ids,
                            use_cache=False,
                        )
                        ref_logits = self.pj_out(ref_outputs.logits)

                        if self.paper_faithful:
                            forward_loss = _compute_colt_forward_cot_loss(
                                self.loss_function,
                                ref_logits,
                                ref_labels,
                                self.config.text_config.vocab_size,
                                has_targets=has_forward_targets,
                            )
                        else:
                            shift_ref_logits = ref_logits[..., :-1, :].contiguous()
                            shift_ref_labels = ref_labels[..., 1:].contiguous()
                            if not has_forward_targets:
                                forward_loss = shift_ref_logits.sum() * 0.0
                            else:
                                forward_loss = self.loss_function(
                                    shift_ref_logits,
                                    shift_ref_labels,
                                    vocab_size=self.config.text_config.vocab_size,
                                )
                        if has_forward_targets:
                            forward_steps_num += 1
                        forward_loss_total += forward_loss
                    # ----------------------------------------------------
                    # C) backward alignment: CoT step (+probe) -> latent
                    # ----------------------------------------------------
                    if self.backward_decoder is not None and i >= 1:
                        backward_ref_idx = (
                            oracle_k_plan[i].backward_index if oracle_k_plan is not None else i - 1
                        )
                        backward_ref_ids = cot_step_id[backward_ref_idx]
                        backward_ref_lens_cpu = [
                            cot_step_len_list[b][backward_ref_idx] for b in range(batch_size)
                        ]
                        backward_ref_lens = torch.tensor(
                            backward_ref_lens_cpu,
                            dtype=torch.long,
                            device=backward_ref_ids.device,
                        )
                        cot_step_attention_mask = (
                            torch.arange(backward_ref_ids.shape[1], device=backward_ref_ids.device)
                            .unsqueeze(0)
                            .expand(batch_size, -1)
                            < backward_ref_lens.unsqueeze(1)
                        ).long()
                        has_backward_targets = any(length > 0 for length in backward_ref_lens_cpu)
                        if not self.oracle_k_enabled and not has_backward_targets:
                            continue
                        backward_active = active_step and has_backward_targets
                        # Encode CoT step, then force one extra "probe" step.
                        # Dummy records keep the same ZeRO-3 call graph but carry zero loss.
                        probe_token = torch.full(
                            (batch_size, 1),
                            self.eos_token_id,
                            dtype=backward_ref_ids.dtype,
                            device=backward_ref_ids.device,
                        )
                        cot_plus_probe_ids = torch.cat([backward_ref_ids, probe_token], dim=1)
                        cot_plus_probe_mask = torch.cat(
                            [
                                cot_step_attention_mask,
                                torch.ones((batch_size, 1), dtype=torch.long, device=current_ref_ids.device),
                            ],
                            dim=1,
                        )
                        probe_positions = torch.full(
                            (batch_size,),
                            cot_plus_probe_ids.shape[1] - 1,
                            dtype=torch.long,
                            device=cot_plus_probe_ids.device,
                        )
                        backward_record = {
                            "input_ids": cot_plus_probe_ids,
                            "attention_mask": cot_plus_probe_mask,
                            "probe_positions": probe_positions,
                            "latent_embd": supervised_latent_embd,
                            "active": backward_active,
                        }
                        if self.batch_aux_decoders:
                            batched_backward_records.append(backward_record)
                        else:
                            decoder_backbone = _get_colt_decoder_backbone(self.backward_decoder)
                            if decoder_backbone is not None:
                                cot_hidden = decoder_backbone(
                                    input_ids=cot_plus_probe_ids,
                                    attention_mask=cot_plus_probe_mask,
                                    use_cache=False,
                                )[0]
                            else:
                                cot_outputs = self.backward_decoder(
                                    input_ids=cot_plus_probe_ids,
                                    attention_mask=cot_plus_probe_mask,
                                    use_cache=False,
                                    output_hidden_states=True,
                                )
                                cot_hidden = cot_outputs.hidden_states[-1]
                            backward_loss = _compute_colt_backward_alignment_loss(
                                cot_hidden,
                                supervised_latent_embd,
                                self.pj_back,
                            )
                            backward_loss_total += backward_loss if backward_active else backward_loss * 0.0
                            if backward_active:
                                backward_steps_num += 1

                # D) Decode the final answer once all ranks have completed the
                # synchronized latent loop, using this rank's local-K state.
                IGNORE_INDEX = -100
                labels = torch.nn.utils.rnn.pad_sequence(
                    answer_id_list, batch_first=True, padding_value=IGNORE_INDEX
                )
                labels = torch.cat(
                    [
                        torch.full((batch_size, 1), IGNORE_INDEX, dtype=labels.dtype, device=labels.device),
                        labels,
                    ],
                    dim=1,
                )
                label_input_ids = torch.nn.utils.rnn.pad_sequence(
                    answer_id_list, batch_first=True, padding_value=self.pad_token_id
                )
                embds = self.model.get_input_embeddings()(label_input_ids)
                embds = torch.concat([latent_embd, embds], dim=1)
                past_seen_tokens = (
                    past_key_values.get_seq_length() if past_key_values is not None else current_seq_len + training_latent_steps
                )
                step_cache_position = torch.arange(
                    past_seen_tokens,
                    past_seen_tokens + embds.shape[1],
                    device=latent_embd.device,
                )
                step_attention_mask = torch.ones(
                    (batch_size, embds.shape[1]), dtype=torch.long, device=latent_embd.device
                )
                outputs = self.model(
                    inputs_embeds=embds,
                    past_key_values=past_key_values,
                    cache_position=step_cache_position,
                    attention_mask=step_attention_mask,
                    position_ids=None,
                    **kwargs,
                )

                logits = self.lm_head(outputs[0])
                ce_loss_total += self.loss_function(
                    logits=logits,
                    labels=labels,
                    vocab_size=self.config.text_config.vocab_size,
                )
            if self.batch_aux_decoders:
                forward_losses = _run_colt_forward_decoder_steps(
                    self.decoder,
                    self.pj_out,
                    self.loss_function,
                    batched_forward_records,
                    self.config.text_config.vocab_size,
                    batched=True,
                )
                for forward_loss, record in zip(forward_losses, batched_forward_records):
                    forward_loss_total += forward_loss
                    if record["has_targets"]:
                        forward_steps_num += 1

                backward_losses = _run_colt_backward_decoder_steps(
                    self.backward_decoder,
                    self.pj_back,
                    batched_backward_records,
                    self.pad_token_id,
                    batched=True,
                )
                for backward_loss, record in zip(backward_losses, batched_backward_records):
                    backward_loss_total += backward_loss
                    if record.get("active", True):
                        backward_steps_num += 1

            forward_loss_total = forward_loss_total / max(forward_steps_num, 1)
            backward_loss_total = backward_loss_total / max(backward_steps_num, 1)
            prediction_loss_total = prediction_loss_total / max(prediction_steps_num, 1)
            self._colt_forward_microbatch_count += 1
            component_log_interval = _colt_component_log_interval()
            should_log_components = (
                component_log_interval > 0
                and self._colt_forward_microbatch_count % component_log_interval == 0
            )
            global_k_metrics = None
            if should_log_components and self.oracle_k_predictor_enabled:
                # Every rank must participate. This aggregates the full effective
                # optimizer batch instead of reporting rank 0's final microbatch.
                global_k_metrics = self._flush_oracle_k_metrics()
            if (
                should_log_components
                and _is_colt_rank_zero()
            ):
                component_losses = torch.stack(
                    [
                        ce_loss_total.detach().float(),
                        forward_loss_total.detach().float(),
                        backward_loss_total.detach().float(),
                        prediction_loss_total.detach().float(),
                    ]
                ).cpu().tolist()
                print(f"ce_loss_total : {component_losses[0]}")
                print(f"forward_loss_total : {component_losses[1]}")
                print(f"backward_loss_total : {component_losses[2]}")
                print(f"prediction_loss_total : {component_losses[3]}")
                if self.oracle_k_predictor_enabled:
                    global_k_loss, global_k_accuracy, global_k_samples = (
                        metric.detach().float().cpu().item() for metric in global_k_metrics
                    )
                    print(f"k_loss_total : {global_k_loss}")
                    print(f"k_accuracy : {global_k_accuracy}")
                    print(f"k_samples_global : {int(global_k_samples)}")
            loss = (
                ce_loss_total
                + self.forward_align_weight * forward_loss_total
                + self.backward_align_weight * backward_loss_total
                + self.prediction_weight * prediction_loss_total
                + self.oracle_k_predictor_loss_weight * k_loss_total
            )

        elif self.latent_reasoning_mode == False:
            outputs = self.model(
                input_ids=input_ids,
                pixel_values=pixel_values,
                pixel_values_videos=pixel_values_videos,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                position_ids=position_ids,
                attention_mask=attention_mask,
                past_key_values=past_key_values,
                inputs_embeds=inputs_embeds,
                cache_position=cache_position,
                **kwargs,
            )

            hidden_states = outputs[0]

            # Only compute necessary logits, and do not upcast them to float if we are not computing the loss
            slice_indices = slice(-logits_to_keep, None) if isinstance(logits_to_keep, int) else logits_to_keep
            logits = self.lm_head(hidden_states[:, slice_indices, :])

            loss = None
            if labels is not None:
                loss = self.loss_function(logits=logits, labels=labels, vocab_size=self.config.text_config.vocab_size)

        return Qwen3VLCausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            rope_deltas=outputs.rope_deltas,
            k_logits=k_logits,
            predicted_k=predicted_k,
        )

    def _forward_latent_reasoning(
        self,
        input_ids: torch.LongTensor,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        num_hidden_generations: int = 0,
        **kwargs: Unpack[TransformersKwargs],
    ) -> Qwen3VLCausalLMOutputWithPast:
        outputs = self.model(
            input_ids=input_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            position_ids=position_ids,
            attention_mask=attention_mask,
            past_key_values=DynamicCache(config=self.config.text_config),
            inputs_embeds=None,
            **kwargs,
        )

        past_key_values = outputs.past_key_values
        hidden_states = outputs[0]
        latent_embd = hidden_states[:, -1:, :]
        latent_embd = self.prj(latent_embd)
        k_logits = self._predict_oracle_k(hidden_states, attention_mask)
        predicted_k = torch.argmax(k_logits, dim=-1) + 1 if k_logits is not None else None
        latent_steps = self._resolve_latent_steps_for_inference(num_hidden_generations, predicted_k=predicted_k)
        self.last_oracle_k_prediction = predicted_k.detach().cpu() if predicted_k is not None else None
        self.last_oracle_k_used = latent_steps
        for i in range(latent_steps):
            past_seen_tokens = past_key_values.get_seq_length()
            step_cache_position = torch.arange(
                past_seen_tokens,
                past_seen_tokens + 1,
                device=latent_embd.device,
            )
            step_attention_mask = torch.ones((latent_embd.shape[0], 1), dtype=torch.long, device=latent_embd.device)
            latent_step_input = self._condition_latent_with_oracle_k(latent_embd, latent_steps, i + 1)
            step_outputs = self.model(
                inputs_embeds=latent_step_input,
                past_key_values=past_key_values,
                cache_position=step_cache_position,
                attention_mask=step_attention_mask,
                position_ids=None,
                **kwargs,
            )
            past_key_values = step_outputs.past_key_values
            latent_embd = self.prj(step_outputs[0][:, -1:, :])
            outputs = step_outputs

        logits = self.lm_head(latent_embd)
        return Qwen3VLCausalLMOutputWithPast(
            loss=None,
            logits=logits,
            past_key_values=past_key_values,
            hidden_states=(latent_embd,),
            rope_deltas=outputs.rope_deltas,
            k_logits=k_logits,
            predicted_k=predicted_k,
        )

    @torch.no_grad()
    def latent_reasoning_generate(
        self,
        input_ids: torch.LongTensor,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        num_hidden_generations: int = 0,
        max_new_tokens: int = 128,
        do_sample: bool = False,
        temperature: float = 1.0,
        top_k: Optional[int] = None,
        eos_token_id: Optional[int] = None,
        prevent_empty_response: bool = False,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.LongTensor:
        latent_outputs = self._forward_latent_reasoning(
            input_ids=input_ids,
            attention_mask=attention_mask,
            position_ids=position_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            num_hidden_generations=num_hidden_generations,
            **kwargs,
        )

        past_key_values = latent_outputs.past_key_values
        latent_embd = latent_outputs.hidden_states[0]
        generated_tokens = []
        eos_id = self.eos_token_id if eos_token_id is None else eos_token_id
        next_input_ids = None
        visible_text_generated = [False] * input_ids.shape[0]

        def select_next_token(logits):
            if do_sample:
                sample_logits = logits / max(temperature, 1e-5)
                if top_k is not None and top_k > 0:
                    topk_values, _ = torch.topk(sample_logits, min(top_k, sample_logits.shape[-1]), dim=-1)
                    min_topk = topk_values[:, -1].unsqueeze(-1)
                    sample_logits = sample_logits.masked_fill(sample_logits < min_topk, float("-inf"))
                probs = torch.softmax(sample_logits, dim=-1)
                return torch.multinomial(probs, num_samples=1)
            return torch.argmax(logits, dim=-1, keepdim=True)

        for generation_step in range(max_new_tokens):
            past_seen_tokens = past_key_values.get_seq_length()
            step_cache_position = torch.arange(
                past_seen_tokens,
                past_seen_tokens + 1,
                device=input_ids.device,
            )
            step_attention_mask = torch.ones((input_ids.shape[0], 1), dtype=torch.long, device=input_ids.device)

            if next_input_ids is None:
                step_outputs = self.model(
                    inputs_embeds=latent_embd,
                    past_key_values=past_key_values,
                    cache_position=step_cache_position,
                    attention_mask=step_attention_mask,
                    position_ids=None,
                    **kwargs,
                )
            else:
                step_outputs = self.model(
                    input_ids=next_input_ids,
                    past_key_values=past_key_values,
                    cache_position=step_cache_position,
                    attention_mask=step_attention_mask,
                    position_ids=None,
                    **kwargs,
                )

            past_key_values = step_outputs.past_key_values
            next_token_logits = self.lm_head(step_outputs[0][:, -1, :])
            next_token = select_next_token(next_token_logits)

            if prevent_empty_response and eos_id is not None:
                proposed_tokens = next_token.squeeze(-1).detach().cpu().tolist()
                blocked_rows = [
                    row
                    for row, token_id in enumerate(proposed_tokens)
                    if token_id == eos_id and not visible_text_generated[row]
                ]
                if blocked_rows:
                    replacement_logits = next_token_logits[blocked_rows].clone()
                    special_ids = [
                        token_id
                        for token_id in self.tokenizer.all_special_ids
                        if 0 <= token_id < replacement_logits.shape[-1]
                    ]
                    replacement_logits[:, special_ids] = float("-inf")
                    next_token[blocked_rows] = select_next_token(replacement_logits)
                    print(
                        f"[latent-generate] prevented_empty_eos step={generation_step} rows={blocked_rows}",
                        flush=True,
                    )

            generated_tokens.append(next_token)
            next_input_ids = next_token
            if prevent_empty_response and not all(visible_text_generated):
                generated_so_far = torch.cat(generated_tokens, dim=1).detach().cpu().tolist()
                for row, token_ids in enumerate(generated_so_far):
                    if not visible_text_generated[row]:
                        visible_text_generated[row] = bool(
                            self.tokenizer.decode(
                                token_ids,
                                skip_special_tokens=True,
                                clean_up_tokenization_spaces=False,
                            ).strip()
                        )
            if eos_id is not None and torch.all(next_token.squeeze(-1) == eos_id):
                break

        if len(generated_tokens) == 0:
            return input_ids
        new_tokens = torch.cat(generated_tokens, dim=1)
        return torch.cat([input_ids, new_tokens], dim=1)

    @torch.no_grad()
    def generate(self, *args, **kwargs):
        if not self.latent_reasoning_mode:
            return super().generate(*args, **kwargs)
        requested_do_sample = kwargs.get("do_sample")
        requested_max_new_tokens = kwargs.get("max_new_tokens")

        if len(args) > 0:
            input_ids = args[0]
        else:
            input_ids = kwargs.pop("input_ids", None)
        if input_ids is None:
            raise ValueError("`input_ids` is required when `latent_reasoning_mode=True`.")

        attention_mask = kwargs.pop("attention_mask", None)
        position_ids = kwargs.pop("position_ids", None)
        pixel_values = kwargs.pop("pixel_values", None)
        pixel_values_videos = kwargs.pop("pixel_values_videos", None)
        image_grid_thw = kwargs.pop("image_grid_thw", None)
        video_grid_thw = kwargs.pop("video_grid_thw", None)
        default_hidden_generations = 0 if self.oracle_k_enabled else self.num_latent
        num_hidden_generations = kwargs.pop("num_hidden_generations", default_hidden_generations)
        respect_generation_args = os.environ.get("COLT_RESPECT_GENERATION_ARGS", "0").strip().lower() in {
            "1",
            "true",
            "yes",
            "on",
        }
        if respect_generation_args:
            max_new_tokens = kwargs.pop("max_new_tokens", 128)
            do_sample = kwargs.pop("do_sample", False)
        else:
            kwargs.pop("max_new_tokens", 128)
            max_new_tokens = 256
            kwargs.pop("do_sample", False)
            do_sample = True
        temperature = kwargs.pop("temperature", 0.6)
        top_k = kwargs.pop("top_k", 20)
        eos_token_id = kwargs.pop("eos_token_id", None)
        prevent_empty_response = kwargs.pop("prevent_empty_response", False)

        generation_config_signature = (
            requested_do_sample,
            do_sample,
            requested_max_new_tokens,
            max_new_tokens,
            prevent_empty_response,
        )
        if generation_config_signature != getattr(self, "_last_logged_generation_config", None):
            print(
                "[latent-generate] "
                f"requested_do_sample={requested_do_sample} "
                f"effective_do_sample={do_sample} "
                f"requested_max_new_tokens={requested_max_new_tokens} "
                f"effective_max_new_tokens={max_new_tokens} "
                f"prevent_empty_response={prevent_empty_response} "
                f"respect_generation_args={respect_generation_args}",
                flush=True,
            )
            self._last_logged_generation_config = generation_config_signature

        return self.latent_reasoning_generate(
            input_ids=input_ids,
            attention_mask=attention_mask,
            position_ids=position_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            num_hidden_generations=num_hidden_generations,
            max_new_tokens=max_new_tokens,
            do_sample=do_sample,
            temperature=temperature,
            top_k=top_k,
            eos_token_id=eos_token_id,
            prevent_empty_response=prevent_empty_response,
            **kwargs,
        )

    def prepare_inputs_for_generation(
        self,
        input_ids,
        past_key_values=None,
        attention_mask=None,
        inputs_embeds=None,
        cache_position=None,
        position_ids=None,
        use_cache=True,
        pixel_values=None,
        pixel_values_videos=None,
        image_grid_thw=None,
        video_grid_thw=None,
        **kwargs,
    ):
        # Overwritten -- in specific circumstances we don't want to forward image inputs to the model

        model_inputs = super().prepare_inputs_for_generation(
            input_ids,
            past_key_values=past_key_values,
            attention_mask=attention_mask,
            inputs_embeds=inputs_embeds,
            cache_position=cache_position,
            position_ids=position_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            use_cache=use_cache,
            **kwargs,
        )

        # Qwen3VL position_ids are prepareed with rope_deltas in forward
        model_inputs["position_ids"] = None

        if cache_position[0] != 0:
            model_inputs["pixel_values"] = None
            model_inputs["pixel_values_videos"] = None

        return model_inputs

    def _get_image_nums_and_video_nums(
        self,
        input_ids: Optional[torch.LongTensor],
        inputs_embeds: Optional[torch.Tensor] = None,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        Get the number of images and videos for each sample to calculate the separation length of the sample tensor.
        These parameters are not passed through the processor to avoid unpredictable impacts from interface modifications.

        Args:
            input_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`):
                Indices of input sequence tokens in the vocabulary.

        Returns:
            image_nums (`torch.LongTensor` of shape `(batch_size, num_images_sample)`)
            video_nums (`torch.LongTensor` of shape `(batch_size, num_videos_sample)`)
        """
        image_token_id = self.config.image_token_id
        video_token_id = self.config.video_token_id
        vision_start_token_id = self.config.vision_start_token_id

        if inputs_embeds is not None:
            vision_start_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(vision_start_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
            image_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(image_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
            video_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(video_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
        else:
            vision_start_mask = input_ids == vision_start_token_id
            image_mask = input_ids == image_token_id
            video_mask = input_ids == video_token_id

        vision_first_mask = torch.roll(vision_start_mask, shifts=1, dims=1)
        image_nums = torch.sum(vision_first_mask & image_mask, dim=1)
        video_nums = torch.sum(vision_first_mask & video_mask, dim=1)

        return image_nums, video_nums

    def _expand_inputs_for_generation(
        self,
        expand_size: int = 1,
        is_encoder_decoder: bool = False,
        input_ids: Optional[torch.LongTensor] = None,
        **model_kwargs,
    ) -> tuple[torch.LongTensor, dict[str, Any]]:
        # Overwritten -- Support for expanding tensors without a batch size dimension
        # e.g., pixel_values, image_grid_thw, pixel_values_videos, video_grid_thw, second_per_grid_t
        # pixel_values.shape[0] is sum(seqlen_images for samples)
        # image_grid_thw.shape[0] is sum(num_images for samples)

        if expand_size == 1:
            return input_ids, model_kwargs

        visual_keys = ["pixel_values", "image_grid_thw", "pixel_values_videos", "video_grid_thw", "second_per_grid_ts"]

        def _expand_dict_for_generation_visual(dict_to_expand):
            image_grid_thw = model_kwargs.get("image_grid_thw", None)
            video_grid_thw = model_kwargs.get("video_grid_thw", None)
            image_nums, video_nums = self._get_image_nums_and_video_nums(
                input_ids, inputs_embeds=model_kwargs.get("inputs_embeds", None)
            )

            def _repeat_interleave_samples(x, lengths, repeat_times):
                samples = torch.split(x, lengths)
                repeat_args = [repeat_times] + [1] * (x.dim() - 1)
                result = torch.cat([sample.repeat(*repeat_args) for sample in samples], dim=0)
                return result

            for key in dict_to_expand:
                if key == "pixel_values":
                    # split images into samples
                    samples = torch.split(image_grid_thw, list(image_nums))
                    # compute the sequence length of images for each sample
                    lengths = [torch.prod(sample, dim=1).sum() for sample in samples]
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "image_grid_thw":
                    # get the num of images for each sample
                    lengths = list(image_nums)
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "pixel_values_videos":
                    samples = torch.split(video_grid_thw, list(video_nums))
                    lengths = [torch.prod(sample, dim=1).sum() for sample in samples]
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "video_grid_thw":
                    lengths = list(video_nums)
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "second_per_grid_ts":
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=list(video_nums), repeat_times=expand_size
                    )
            return dict_to_expand

        def _expand_dict_for_generation(dict_to_expand):
            for key in dict_to_expand:
                if (
                    key != "cache_position"
                    and dict_to_expand[key] is not None
                    and isinstance(dict_to_expand[key], torch.Tensor)
                    and key not in visual_keys
                ):
                    dict_to_expand[key] = dict_to_expand[key].repeat_interleave(expand_size, dim=0)
            return dict_to_expand

        model_kwargs = _expand_dict_for_generation_visual(model_kwargs)

        if input_ids is not None:
            input_ids = input_ids.repeat_interleave(expand_size, dim=0)

        model_kwargs = _expand_dict_for_generation(model_kwargs)

        if is_encoder_decoder:
            if model_kwargs.get("encoder_outputs") is None:
                raise ValueError("If `is_encoder_decoder` is True, make sure that `encoder_outputs` is defined.")
            model_kwargs["encoder_outputs"] = _expand_dict_for_generation(model_kwargs["encoder_outputs"])

        return input_ids, model_kwargs


__all__ = [
    "Qwen3VLVisionModel",
    "Qwen3VLForConditionalGeneration",
    "Qwen3VLModel",
    "Qwen3VLPreTrainedModel",
    "Qwen3VLTextModel",
]
